_ALL = [ApplyHair, ApplyFur, ApplyMaterial, Bake, Delete, Flatten, Generate, Reapply, Regenerate, ToggleBakeFlag,
        ToggleSection, Unbake, DismissBakeResult]
_WORKING_ON_A_CHARACTER = [ApplyHair, ApplyFur, ApplyMaterial, Bake, Delete, Flatten, Generate, Reapply,
                           Regenerate, Unbake]

_ASSET_NUMBERS = itertools.count()


@pytest.fixture
def asset_name():
    return f"optest{next(_ASSET_NUMBERS)}_{os.getpid()}"


@pytest.mark.parametrize("operator", _ALL, ids=lambda operator: operator.bl_idname)
def test_operator_is_registered(operator):
    namespace, name = operator.bl_idname.split(".")
    assert hasattr(getattr(bpy.ops, namespace), name)


def test_toggles_push_no_undo_step():
    """Folding a section or ticking a bake setting is not a scene change, an undo step for it is slow and confusing."""
    for operator in (ToggleBakeFlag, ToggleSection, DismissBakeResult):
        assert 'UNDO' not in operator.bl_options


def test_bake_is_its_own_undo_step():
    """The bake pushes its own undo step once the result is in, letting blender push one would capture the half
    prepared scene of the background bake."""
    assert 'UNDO' not in Bake.bl_options


@pytest.mark.parametrize("operator", _WORKING_ON_A_CHARACTER, ids=lambda operator: operator.bl_idname)
def test_operators_only_show_up_with_a_character(scratch, operator):
    ObjectService.deselect_and_deactivate_all()
    assert not operator.poll(bpy.context)
    select(make_grid("optest_unrelated"))
    assert not operator.poll(bpy.context)


@pytest.mark.parametrize("operator", _WORKING_ON_A_CHARACTER, ids=lambda operator: operator.bl_idname)
def test_operators_work_from_the_character(character, operator):
    select(character)
    assert operator.poll(bpy.context)


# ---------------------------------------------------------------------------
# Folding sections
# ---------------------------------------------------------------------------

def test_sections_fold_per_asset(asset_name):
    other = f"{asset_name}_other"
    assert not toggle_section_operator.is_open(asset_name, "maps")
    assert toggle_section_operator.is_open(asset_name, "maps", default=True)

    bpy.ops.mpfb.toggle_hair_section(hair_asset=asset_name, section="maps", default_open=False)
    assert toggle_section_operator.is_open(asset_name, "maps")
    assert not toggle_section_operator.is_open(other, "maps"), "one asset's folds are not another's"
    assert not toggle_section_operator.is_open(asset_name, "lights")

    bpy.ops.mpfb.toggle_hair_section(hair_asset=asset_name, section="maps", default_open=False)
    assert not toggle_section_operator.is_open(asset_name, "maps")


def test_section_open_by_default_folds_on_the_first_click(asset_name):
    bpy.ops.mpfb.toggle_hair_section(hair_asset=asset_name, section="colour", default_open=True)
    assert not toggle_section_operator.is_open(asset_name, "colour", default=True)


def test_forgetting_an_asset_drops_only_its_folds(asset_name):
    other = f"{asset_name}_other"
    bpy.ops.mpfb.toggle_hair_section(hair_asset=asset_name, section="maps")
    bpy.ops.mpfb.toggle_hair_section(hair_asset=other, section="maps")
    toggle_section_operator.forget_asset(asset_name)
    assert not toggle_section_operator.is_open(asset_name, "maps")
    assert toggle_section_operator.is_open(other, "maps")
    toggle_section_operator.forget_asset(other)


