def _flip(basemesh, asset, setting, default=False, fur=False):
    return run_hardened(ToggleBakeFlag, basemesh, hair_asset=asset, setting=setting, is_fur=fur,
                        default_value=default)


def test_bake_setting_is_flipped(character, asset_name):
    hp.create_cards_bake_properties(HAIR_PROPERTIES, character, asset_name)
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_glossy", None, entity_reference=character) is True
    result, report = _flip(character, asset_name, "cards_glossy", default=True)
    assert result == {'FINISHED'}
    report.assert_no_errors()
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_glossy", None, entity_reference=character) is False
    _flip(character, asset_name, "cards_glossy", default=True)
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_glossy", None, entity_reference=character) is True


def test_bake_setting_of_an_older_file_is_created_first(character, asset_name):
    """A file saved before a setting existed has no definition for it, the click must still work."""
    result, report = _flip(character, asset_name, "cards_bake_flow")
    assert result == {'FINISHED'}
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_bake_flow", None, entity_reference=character) is True
    # And the rest of the bake settings came along with it
    assert HAIR_PROPERTIES.has_key(f"{asset_name}_cards_resolution", entity_reference=character)


def test_fur_bake_setting_goes_to_the_fur_settings(character, asset_name):
    _flip(character, asset_name, "cards_double_sided", fur=True)
    assert FUR_PROPERTIES.get_value(f"{asset_name}_cards_double_sided", None, entity_reference=character) is True
    assert not HAIR_PROPERTIES.has_key(f"{asset_name}_cards_double_sided", entity_reference=character)


@pytest.mark.parametrize("asset, setting", [("", "cards_glossy"), ("bob", "")])
def test_bake_setting_needs_a_name(character, asset, setting):
    result, report = _flip(character, asset, setting)
    assert result == {'CANCELLED'}
    report.assert_reported('ERROR', "No bake setting")


