def test_regenerate_refuses_baked_cards(character, asset_name):
    hp.set_cards_flag(HAIR_PROPERTIES, character, asset_name, "hair", "generated", True)
    hp.set_cards_flag(HAIR_PROPERTIES, character, asset_name, "hair", "baked", True)
    result, report = run_hardened(Regenerate, character, hair_asset=asset_name, is_fur=False)
    assert result == {'CANCELLED'}
    report.assert_reported('ERROR', "unbake first")


def test_unbake_of_baked_cards_whose_hair_is_gone(character, asset_name):
    """Unbaking still clears the baked state when the hair object was deleted by hand; there is nothing to rebuild."""
    hp.set_cards_flag(HAIR_PROPERTIES, character, asset_name, "hair", "generated", True)
    hp.set_cards_flag(HAIR_PROPERTIES, character, asset_name, "hair", "baked", True)
    result, _report = run_hardened(Unbake, character, hair_asset=asset_name, is_fur=False)
    assert result == {'FINISHED'}
    assert not hp.get_cards_flag(HAIR_PROPERTIES, character, asset_name, "hair", "baked")
    assert not hp.get_cards_flag(HAIR_PROPERTIES, character, asset_name, "hair", "generated"), \
        "with nothing rebuilt, Convert to cards has to be offered again"


