# ---------------------------------------------------------------------------
# Deleting what is left of an asset
# ---------------------------------------------------------------------------

def _some_properties(basemesh, asset):
    hp.create_cards_bake_properties(HAIR_PROPERTIES, basemesh, asset)
    hp.set_cards_flag(HAIR_PROPERTIES, basemesh, asset, "hair", "generated", True)


def _keys_of(basemesh, asset):
    return [key for key in HAIR_PROPERTIES.get_keys(basemesh) if key.startswith(f"{asset}_")]


def test_delete_cleans_up_after_a_hair_object_deleted_by_hand(character, asset_name):
    _some_properties(character, asset_name)
    hp.remember_cards_settings(character, asset_name, {"cards_segments": 3})
    bpy.ops.mpfb.toggle_hair_section(hair_asset=asset_name, section="maps")

    result, report = run_hardened(Delete, character, hair_asset=asset_name, is_fur=False)
    assert result == {'FINISHED'}
    report.assert_reported('WARNING', "only cleaning up")
    assert not _keys_of(character, asset_name)
    assert hp.read_cards_settings(character, asset_name) == {}
    assert not toggle_section_operator.is_open(asset_name, "maps")


def test_delete_leaves_an_asset_with_a_longer_name_alone(character, asset_name):
    longer = f"{asset_name}_long"
    _some_properties(character, asset_name)
    _some_properties(character, longer)
    try:
        run_hardened(Delete, character, hair_asset=asset_name, is_fur=False)
        assert not _keys_of(character, f"{asset_name}_cards")
        assert HAIR_PROPERTIES.has_key(f"{longer}_cards_resolution", entity_reference=character)
    finally:
        HAIR_PROPERTIES.remove_dynamic_keys_with_prefix(f"{longer}_", character)


def test_delete_also_removes_settings_of_older_versions(character, asset_name):
    """A file saved by an older version can carry card settings which no longer exist (fold states used to be some)."""
    _some_properties(character, asset_name)
    legacy = f"{HAIR_PROPERTIES.dynamic_prefix}{asset_name}_cards_ui_placement_open"
    character[legacy] = True
    run_hardened(Delete, character, hair_asset=asset_name, is_fur=False)
    assert legacy not in character.keys()


def test_asset_properties_are_told_apart():
    assert hp.is_asset_property("bob_length", "bob", "hair")
    assert hp.is_asset_property("bob_cards_resolution", "bob", "hair")
    assert hp.is_asset_property("bob_hair_cards_are_baked", "bob", "hair")
    assert hp.is_asset_property("bob_cards_setting_of_a_future_version", "bob", "hair")
    assert not hp.is_asset_property("bob_long_length", "bob", "hair"), "that is the slider of bob_long"
    assert not hp.is_asset_property("bob_long_cards_resolution", "bob", "hair")
    assert not hp.is_asset_property("bobby_length", "bob", "hair")
    assert hp.is_asset_property("fluff_holes", "fluff", "fur")
    assert not hp.is_asset_property("bob_holes", "bob", "hair"), "holes is a fur only slider"


def test_delete_leaves_other_assets_alone(character, asset_name):
    other = f"other{asset_name}"
    _some_properties(character, asset_name)
    _some_properties(character, other)
    try:
        run_hardened(Delete, character, hair_asset=asset_name, is_fur=False)
        assert _keys_of(character, other)
        assert hp.get_cards_flag(HAIR_PROPERTIES, character, other, "hair", "generated")
    finally:
        HAIR_PROPERTIES.remove_dynamic_keys_with_prefix(f"{other}_", character)


def test_delete_releases_baked_images(character, asset_name):
    """The extra maps carry a fake user so that they survive in the file, delete has to release it."""
    names = hp.baked_image_names(asset_name)
    for name in names:
        bpy.data.images.new(name, 4, 4).use_fake_user = True
    run_hardened(Delete, character, hair_asset=asset_name, is_fur=False)
    for name in names:
        assert name not in bpy.data.images


# ---------------------------------------------------------------------------
# How a background bake ended. Its operator is gone by then, so it cannot report() the result itself
# ---------------------------------------------------------------------------

def test_failed_background_bake_is_kept_until_dismissed(asset_name):
    _bake._announce_background_result("optest_body", asset_name, _results.BAKE_FAILED, [('ERROR', "It broke")])
    try:
        assert _results.last_bake_result("optest_body", asset_name) == {
            "status": _results.BAKE_FAILED, "messages": [('ERROR', "It broke")]}
        assert _results.last_bake_result("optest_other_body", asset_name) is None, "kept per character"
        dismiss = operator_mock(DismissBakeResult, hair_asset=asset_name, basemesh_name="optest_body")
        assert DismissBakeResult.hardened_execute(dismiss, bpy.context) == {'FINISHED'}
        assert _results.last_bake_result("optest_body", asset_name) is None
    finally:
        _results.forget_asset(asset_name)


def test_clean_background_bake_clears_an_older_result(asset_name):
    _results.remember_bake_result("optest_body", asset_name, _results.BAKE_WARNINGS, [('WARNING', "Hm")])
    _bake._announce_background_result("optest_body", asset_name, None, [])
    assert _results.last_bake_result("optest_body", asset_name) is None


def test_forgetting_an_asset_drops_its_results_on_every_character(asset_name):
    for body in ("optest_body", "optest_other_body"):
        _results.remember_bake_result(body, asset_name, _results.BAKE_CANCELLED, [])
    _results.remember_bake_result("optest_body", f"{asset_name}_kept", _results.BAKE_CANCELLED, [])
    try:
        _results.forget_asset(asset_name)
        assert _results.last_bake_result("optest_body", asset_name) is None
        assert _results.last_bake_result("optest_other_body", asset_name) is None
        assert _results.last_bake_result("optest_body", f"{asset_name}_kept") is not None
    finally:
        _results.forget_asset(f"{asset_name}_kept")


def test_every_bake_ending_has_a_title():
    titles = {_results.bake_result_title(status) for status in (_results.BAKE_FAILED, _results.BAKE_CANCELLED,
                                                                  _results.BAKE_ABANDONED, _results.BAKE_WARNINGS)}
    assert len(titles) == 4


